from pathlib import Path

runner = Path('.dev/probe_schema_nested_hash.py').read_text()
start = runner.index("old = '''")
end = runner.index('assert source.count(old)', start)
old = '''def _filter_schema_json(value: Any) -> Any:
    """Apply the encoder's filters to an already JSON-serialized model dump."""
    if type(value) is dict:
        return {
            key: _filter_schema_json(item) for key, item in value.items()
            if item is not None and not key.startswith("_sa")
        }
    if type(value) is list:
        # None elements in arrays survive exclude_none, just as upstream.
        return [_filter_schema_json(item) for item in value]
    return value
'''
new = '''def _filter_schema_json(value: Any) -> Any:
    """Filter only the freshly owned JSON-mode model dump in place."""
    pending = [value]
    while pending:
        container = pending.pop()
        if type(container) is dict:
            for key in tuple(container):
                item = container[key]
                if item is None or key.startswith("_sa"):
                    del container[key]
                elif type(item) in (dict, list):
                    pending.append(item)
        elif type(container) is list:
            pending.extend(item for item in container if type(item) in (dict, list))
    return value
'''
runner = runner[:start] + 'old = ' + repr(old) + '\nnew = ' + repr(new) + '\n' + runner[end:]
runner = runner.replace('schema-nested-hash-probe', 'schema-owned-filter-probe').replace('schema_nested_hash_candidate', 'schema_owned_filter_candidate').replace('schema-nested-hash-probe/v1', 'schema-owned-filter-probe/v1')
runner = runner.replace('pa-nested-schema-', 'pa-owned-schema-')
runner = runner.replace('Unshipped call-local nested schema hash memo', 'Unshipped owned-schema JSON filter')
target = Path('.dev/probe_schema_owned_filter.py')
assert not target.exists()
target.write_text(runner)

