import json
import pydantic_core

def native_graph(value, active=None, depth=0):
    kind=type(value)
    if kind in (type(None),bool,str,float):return True
    # Avoid extending Python's configurable large-integer rendering limit.
    if kind is int:return value.bit_length()<=1024
    if kind not in (list,dict) or depth>=64:return False
    if active is None:active=set()
    identity=id(value)
    if identity in active:return False
    active.add(identity)
    try:
        if kind is dict:
            return all(type(k) is str and native_graph(v,active,depth+1) for k,v in value.items())
        return all(native_graph(v,active,depth+1) for v in value)
    finally:active.remove(identity)

def encode(value):
    if pydantic_core.__version__=='2.46.4' and native_graph(value):
        try:
            return pydantic_core.to_json(value,ensure_ascii=True,inf_nan_mode='constants')
        except (ValueError,TypeError,OverflowError):
            pass
    return json.dumps(value,default=str).encode()

